"""Player/block-position conversion using Bookshelf block output."""
js(PACK/'data/vr/tags/block/conversion_disallowed.json',{'values':['minecraft:air','minecraft:cave_air','minecraft:void_air','minecraft:water','minecraft:lava','minecraft:bubble_column','minecraft:bedrock','minecraft:barrier','minecraft:structure_void','minecraft:nether_portal','minecraft:end_portal','minecraft:end_gateway','minecraft:fire','minecraft:soul_fire','minecraft:piston_head','minecraft:moving_piston',{'id':'#minecraft:doors','required':False},{'id':'#minecraft:beds','required':False},{'id':'#minecraft:tall_flowers','required':False},'minecraft:tall_grass','minecraft:large_fern','minecraft:tall_seagrass','minecraft:small_dripleaf']})
fn('spawn/from_block','return run function vr:spawn/convert_block')
fn('spawn/convert_block','execute unless loaded ~ ~ ~ run return 0','execute if block ~ ~ ~ #vr:conversion_disallowed run return 0','scoreboard players set #block_read vr.tmp 0','execute store success score #block_read vr.tmp run function #bs.block:get_block','execute unless score #block_read vr.tmp matches 1 run return 0','execute unless data storage bs:out block.type run return 0','data modify storage vr:work conversion.verify set value {type:"minecraft:air",state:""}','data modify storage vr:work conversion.verify.type set from storage bs:out block.type','execute if data storage bs:out block.state run data modify storage vr:work conversion.verify.state set from storage bs:out block.state','execute store result score #source_valid vr.tmp run function vr:spawn/validate_source with storage vr:work conversion.verify','execute unless score #source_valid vr.tmp matches 1 run return 0','data modify storage vr:work conversion.display set value {id:"minecraft:air",properties:{}}','data modify storage vr:work conversion.display.id set from storage bs:out block.type','execute if data storage bs:out block.properties run data modify storage vr:work conversion.display.properties set from storage bs:out block.properties','scoreboard players set #converted vr.tmp 0','execute positioned ~0.5 ~0.5 ~0.5 summon minecraft:marker run function vr:spawn/converted_root','execute unless score #converted vr.tmp matches 1 run return run function vr:spawn/conversion_rollback','scoreboard players set #removed vr.tmp 0','execute store success score #removed vr.tmp run setblock ~ ~ ~ minecraft:air','execute unless score #removed vr.tmp matches 1 run return run function vr:spawn/conversion_rollback','return 1')
fn('spawn/converted_root','tag @s add vr.root','function vr:shape/cube/init','scoreboard players operation #converted_id vr.tmp = @s vr.id','execute as @e[type=minecraft:block_display,tag=vr.display] if score @s vr.id = #converted_id vr.tmp run function vr:spawn/converted_display')
fn('spawn/converted_display','data modify entity @s block_state set from storage vr:work conversion.display','scoreboard players set #converted vr.tmp 1')
fn('spawn/conversion_rollback','execute as @e[type=minecraft:block_display,tag=vr.display] if score @s vr.id = #converted_id vr.tmp run kill @s','execute as @e[type=minecraft:marker,tag=vr.root] if score @s vr.id = #converted_id vr.tmp run kill @s','return 0')
fn('spawn/looked_block','execute unless entity @s[type=minecraft:player] run return 0','execute store result storage vr:work conversion_view.reach double 0.0001 run attribute @s minecraft:block_interaction_range get 10000','return run function vr:spawn/looked_block_macro with storage vr:work conversion_view')
fn('spawn/looked_block_macro','$return run function #bs.view:at_aimed_block {run:"function vr:spawn/from_block",with:{entities:false,blocks:"function #bs.hitbox:callback/get_block_shape",max_distance:$(reach)}}')

fn('spawn/validate_source','$execute unless block ~ ~ ~ $(type)$(state) run return 0','return 1')
